  "content": "package com.quotehub.platform.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.quotehub.platform.dto.ApiResponse;
import com.quotehub.platform.entity.QuoteTemplate;
import com.quotehub.platform.service.TemplateService;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

@RestController
@RequestMapping("/api/templates")
public class TemplateController {

    private final TemplateService templateService;
    private final ObjectMapper objectMapper;

    public TemplateController(TemplateService templateService, ObjectMapper objectMapper) {
        this.templateService = templateService;
        this.objectMapper = objectMapper;
    }

    @PostMapping("/upload")
    public ApiResponse<QuoteTemplate> upload(@RequestParam("file") MultipartFile file,
                                             @RequestParam("name") String name,
                                             @RequestParam(value = "description", required = false) String description,
                                             Authentication authentication) {
        try {
            QuoteTemplate template = templateService.upload(file, name, description, currentUserId(authentication));
            return ApiResponse.success("上传成功", template);
        } catch (IOException e) {
            return ApiResponse.error(500, "上传失败: " + e.getMessage());
        }
    }

    @GetMapping
    public ApiResponse<List<QuoteTemplate>> list() {
        return ApiResponse.success(templateService.findAll());
    }

    @GetMapping("/{id}")
    public ApiResponse<QuoteTemplate> detail(@PathVariable("id") Long id) {
        QuoteTemplate template = templateService.findById(id);
        if (template == null) {
            return ApiResponse.error(404, "模板不存在");
        }
        return ApiResponse.success(template);
    }

    @GetMapping("/{id}/download")
    public ResponseEntity<byte[]> download(@PathVariable("id") Long id) throws IOException {
        QuoteTemplate template = templateService.findById(id);
        if (template != null && template.getFilePath() != null) {
            Path path = Paths.get(template.getFilePath());
            if (Files.isRegularFile(path)) {
                return ResponseEntity.ok()
                        .contentType(MediaType.APPLICATION_OCTET_STREAM)
